// A coverage axis's `percent` is the double `covered / total * 100` rounded to
// one decimal by its EXACT decimal value, ties to even — the result Python's
// `round(x, 1)` gives, which is how every client rounds today — and 0 when
// `total` is 0.
//
// The oracle is Python's own answer for EVERY (covered, total) pair with
// 0 <= covered <= total < 1500, generated by
// tests/fixtures/coverage-percent-oracle.gen.py (see the fixture's header for
// its encoding). The board's rounding is the coverage codecs' one function,
// `coveragePercent(covered, total)` in src/codecs/coverage.ts; the same
// rounding is held through `POST /api/v2/runs` in
// tests/run-ingest-decodes-coverage.test.ts.
import { describe, test, expect } from "bun:test";
import { coveragePercent } from "../src/codecs/coverage.ts";
import { loadCoveragePercentOracle } from "./helpers/coverage-percent-oracle.ts";

const oracle = loadCoveragePercentOracle();

describe("coveragePercent — rounds as the clients round", () => {
  test("equals Python's round(covered / total * 100, 1) for every pair with total below 1500", () => {
    const mismatches: string[] = [];
    let checked = 0;
    for (let total = 0; total < oracle.totalBelow; total++) {
      for (let covered = 0; covered <= total; covered++) {
        const expected = oracle.percent(covered, total);
        const actual = coveragePercent(covered, total);
        checked++;
        if (actual !== expected) {
          mismatches.push(`${covered}/${total}: expected ${expected}, got ${actual}`);
        }
      }
    }
    // Every pair of the table was compared — none skipped.
    expect(checked).toBe(1_125_750);
    expect(checked).toBe(oracle.pairs);
    // The first few disagreements name the defect; the count bounds it.
    expect(mismatches.slice(0, 20)).toEqual([]);
    expect(mismatches.length).toBe(0);
  });

  test("1 covered of 80 is 1.2 — Python's tie to even — never the naive 1.3", () => {
    // The oracle itself says 1.2 (Python's answer), and a naive JavaScript
    // rounding says 1.3: the pair genuinely separates the two.
    expect(oracle.percent(1, 80)).toBe(1.2);
    expect(Math.round((1 / 80) * 100 * 10) / 10).toBe(1.3);
    expect(Number(((1 / 80) * 100).toFixed(1))).toBe(1.3);

    expect(coveragePercent(1, 80)).toBe(1.2);
    expect(coveragePercent(1, 80)).not.toBe(1.3);
  });

  test("a total of 0 gives percent 0, never NaN", () => {
    const percent = coveragePercent(0, 0);
    expect(percent).toBe(0);
    expect(Number.isNaN(percent)).toBe(false);
  });

  test("a whole axis stays whole: 0 of N is 0 and N of N is 100", () => {
    expect(coveragePercent(0, 7)).toBe(0);
    expect(coveragePercent(7, 7)).toBe(100);
    expect(coveragePercent(1499, 1499)).toBe(100);
  });
});
